1	import type { Server } from "node:http";
2	import { monitorEventLoopDelay } from "node:perf_hooks";
3	import type { Assertion } from "../src/checks/assertions";
4	import { checkCert } from "../src/checks/cert";
5	import { checkDns, type Ask, type DnsRecord } from "../src/checks/dns";
6	import { checkHttp } from "../src/checks/http";
7	import { checkStripe, type StripeRuntime } from "../src/checks/stripe";
8	import { checkSupabase } from "../src/checks/supabase";
9	import { serviceFetch, type ServiceFetch } from "../src/checks/service-fetch";
10	import { SERVICE_KEY, type StripeConfig, type SupabaseConfig } from "../src/lib/service-monitor";
11	import { checkTcp } from "../src/checks/tcp";
12	import type { AddressGuard, CheckResult } from "../src/checks/types";
13	import { Rdap, asciiHost, guardedFetch } from "../src/checks/rdap";
14	import { DOMAIN_LOOK_SEC, domainLeader, domainPass, type DomainStore } from "./domains";
15	import { askConfirm, peerServer, sendReports, type Report } from "./peer";
16	import { merged, Rollups, WINDOW_SEC, type RollupRow } from "./rollup";
17	import { confirmersFor, eligible, hash32, nextDue, ranked, TimerWheel, type ProbeInfo } from "./schedule";
18	import { DEADLINE_MARGIN_MS, plan } from "./heartbeat";
19	import { needsConfirmation, type Located } from "./state";
20	import type { Applied, HeartbeatJudged, HeartbeatMonitor, Monitor, ProbeRow } from "./store";
21	import { monitorDefaults } from "../src/lib/monitor-defaults";
22	import { Canary } from "./canary";
23	
24	/* One probe: the timer wheel, the checks, confirmation, delivery to the store for monitors it is
25	   home for, and the rollups of its own checks (`schedule.ts` explains who does what).
26	
27	   A check's life: it comes due on the wheel, runs (at most `maxInFlight` at once), and lands in
28	   this location's rollup. A failure that needs a second location is re-checked at once by the
29	   next location in the ranking that answers, or by this probe itself after a pause when no other
30	   location is live; when others are live and none answers within 30 s, it stays unconfirmed.
31	   A second look waits for no ordinary check: it takes the next free slot, in the order the
32	   second looks asked. The outcome
33	   then goes to the monitor's home, batched once a second, and only the home
34	   hands the outcome to the store, which steps the locked monitor row.
35	
36	   A heartbeat is never checked: the receiver records its pings (`ingest/`), and its home judges
37	   them. The home learns of a ping from the 30-second refresh, which reads every heartbeat's
38	   newest ping times, so a ping is judged within about 30 seconds of arriving; a deadline (an
39	   expected run plus its grace, or a `/start` plus the max run time) sits on the same timer
40	   wheel as the checks, in memory only, and is judged 5 seconds after it falls. Each judgement
41	   steps the row through the store (`judgeHeartbeat`), under the same lock and reducer as an
42	   outcome. A ping that lands while no probe is live stays recorded, and the first home to come
43	   back judges it, and every deadline that passed meanwhile, in order (`heartbeat.ts`).
44	
45	   A window is written when it closes, so a monitor's numbers reach the dashboard 5 to 10 minutes
46	   after its first check. A version this probe loaded as unchecked is the exception: the moment
47	   its first check here completes, that monitor's window so far is written on its own, and the
48	   window starts counting again from nothing, so its close adds only what came after. That is one
49	   extra write per new (or edited, or resumed) monitor and location, never one per check.
50	
51	   The fleet's leader also looks up the domains of the SSL monitors' hosts once a day
52	   (`domains.ts`). */
53	
54	export type ProbeStore = {
55	  heartbeat(p: ProbeRow): Promise<void>;
56	  /** Out of the live set at once, so a planned restart doesn't leave the others asking a probe
57	      that won't answer for the two minutes a heartbeat stays live. */
58	  leave(id: string): Promise<void>;
59	  liveProbes(): Promise<ProbeRow[]>;
60	  loadMonitors(): Promise<Monitor[]>;
61	  flushRollups(rows: RollupRow[]): Promise<void>;
62	  /** Step the current row under its lock, with version, ordering and replay fences. */
63	  apply(report: Report): Promise<Applied>;
64	  /** Heartbeats, for a store that has them (the in-memory stores of the tests and the benchmark
65	      don't): their settings and what has arrived, and one judgement of the next due event. */
66	  loadHeartbeats?(): Promise<HeartbeatMonitor[]>;
67	  judgeHeartbeat?(monitorId: string, location: string): Promise<HeartbeatJudged>;
68	  /** Domain registrations, for a store that has them (`domains.ts`). */
69	  loadDomains?: DomainStore["loadDomains"];
70	  recordDomain?: DomainStore["recordDomain"];
71	};
72	
73	export type ProbeOptions = {
74	  self: ProbeRow;
75	  secret: string;
76	  store: ProbeStore;
77	  /** Where the peer server listens; `self.url` is how the others reach it. */
78	  port: number;
79	  host?: string;
80	  maxInFlight?: number;
81	  /** Seconds to wait before re-checking a failure from here when no other location is live. */
82	  recheckAfterSec?: number;
83	  now?: () => number;
84	  /** For tests and the benchmark: an address guard that admits a local target, its CA, and a
85	      DNS resolver that isn't the network. */
86	  checks?: { allow?: AddressGuard; ca?: string | Buffer; dnsAsk?: Ask; serviceFetch?: ServiceFetch };
87	  /** The checks due in one second start spread across it, each at its own offset, so a second
88	      never begins with every handshake at once. Tests set 0. */
89	  spreadMs?: number;
90	  /** Seconds between the background jobs; tests drive them by hand instead (`timers: false`). */
91	  timers?: boolean;
92	  /** How the leader reads RDAP: the guarded network fetch by default; a test passes one over
93	      recorded answers, or false for none. */
94	  rdap?: Rdap | false;
95	  /** The process installs the real canary; tests inject recorded network answers. */
96	  canary?: Canary;
97	  release?: string;
98	};
99	
100	const FLUSH_GRACE_SEC = 5;
101	/** When a monitor version began, in epoch seconds: a version is its row's `updated_at` in whole
102	 *  microseconds (`probe_load_monitors`). Anything else (the tests' "1", "2") reads as the start of
103	 *  time, so a new version drops every window held for the old one. */
104	export function versionSec(version: string): number {
105	  const us = Number(version);
106	  return /^\d{16}$/.test(version) && Number.isSafeInteger(us) ? us / 1e6 : -Infinity;
107	}
108	const MAX_OUTBOX = 50_000;
109	/** A failure is confirmed from a second location within 30 s (`spec.md § 2`), however many are asked. */
110	const CONFIRM_WITHIN_MS = 30_000;
111	const SUPABASE_REFUSAL_SEC = 30 * 60;
112	
113	/** Scheduling only: a refusal is the status already kept on the latest failure or open
114	 * incident. An unconfirmed refusal while up needs no backoff; 429 is temporary throttling,
115	 * not a refused key/read. Recovery leaves down through the ordinary reducer. */
116	export function supabaseBackoff(m: Monitor): boolean {
117	  const refusal = (s: unknown) => typeof s === "number" && s >= 400 && s < 500 && s !== 429;
118	  return m.type === "supabase" && m.config.__state === "down"
119	    && (refusal(m.config.__failureStatus) || refusal(m.config.__incidentStatus));
120	}
121	/** Events one heartbeat judges in a row before giving the others a turn. */
122	const JUDGE_BATCH = 50;
123	
124	export class Probe {
125	  readonly monitors = new Map<string, Monitor>();
126	  readonly heartbeats = new Map<string, HeartbeatMonitor>();
127	  peers: ProbeRow[] = [];
128	  readonly wheel: TimerWheel;
129	  readonly rollups: Rollups;
130	  private unflushed: RollupRow[] = [];
131	  private outbox: Report[] = [];
132	  private inFlight = 0;
133	  private waiting: (() => void)[] = [];
134	  private waitingUrgent: (() => void)[] = [];
135	  private running = new Set<Promise<unknown>>();
136	  private timers: NodeJS.Timeout[] = [];
137	  private server?: Server;
138	  private lag = monitorEventLoopDelay({ resolution: 20 });
139	  private startedAt: number;
140	  readonly counts = { checks: 0, confirms: 0, unconfirmed: 0, reported: 0, applied: 0, duplicates: 0, moved: 0, judged: 0, firstWrites: 0, domains: 0, errors: 0 };
141	  private readonly rdap: Rdap | null;
142	  private stopping = false;
143	  private lastFlushAt: number | null = null;
144	  /** Request start times, including second looks. Scheduling data stays in memory; after a
145	      restart the feed reconstructs a conservative bound from failures and the counted outcome. */
146	  private serviceChecked = new Map<string, { version: string; at: number }>();
147	
148	  constructor(readonly o: ProbeOptions) {
149	    this.wheel = new TimerWheel(this.now() - 1);
150	    this.rollups = new Rollups(o.self.location);
151	    this.startedAt = this.now();
152	    this.rdap = o.rdap === false ? null : (o.rdap ?? new Rdap(guardedFetch({ allow: o.checks?.allow, ca: o.checks?.ca })));
153	  }
154	
155	  now(): number {
156	    return this.o.now ? this.o.now() : Math.floor(Date.now() / 1000);
157	  }
158	
159	  async start(): Promise<void> {
160	    this.lag.enable();
161	    await this.o.store.heartbeat(this.o.self);
162	    this.peers = await this.o.store.liveProbes();
163	    await this.refresh();
164	    if (this.o.canary) await this.o.canary.test(true);
165	    this.server = peerServer(this.o.secret, {
166	      confirm: (id, version) => this.confirmHere(id, version),
167	      report: (reports) => this.receive(reports),
168	      health: () => this.health(),
169	    });
170	    await new Promise<void>((resolve) => this.server!.listen(this.o.port, this.o.host ?? "0.0.0.0", resolve));
171	    if (this.o.timers === false) return;
172	    const every = (sec: number, fn: () => Promise<unknown> | void) =>
173	      this.timers.push(
174	        setInterval(() => {
175	          Promise.resolve(fn()).catch(() => this.counts.errors++);
176	        }, sec * 1000),
177	      );
178	    every(1, () => {
179	      this.tick();
180	    });
181	    every(1, () => this.sendOutbox());
182	    every(15, () => this.beat());
183	    every(30, () => this.refresh());
184	    every(30, () => this.flush());
185	    every(10, () => this.o.canary?.test());
186	  }
187	
188	  /** A planned stop hands its monitors over only once it has nothing left to write. It takes no
189	      more confirmations or reports, finishes its own checks and writes them as their home, and
190	      only then leaves the live set.
191	      While it drains, the others get no answer from it, so their failures stay unconfirmed:
192	      nothing opens that shouldn't, and their reports wait for the next home. Whatever still
193	      overlaps (a request already being read when the server closed, a drain that outlasts the
194	      two minutes a heartbeat stays live) is serialized by the monitor row lock. */
195	  async stop(): Promise<void> {
196	    this.stopping = true;
197	    for (const t of this.timers) clearInterval(t);
198	    this.timers = [];
199	    const closed = new Promise<void>((resolve) => (this.server ? this.server.close(() => resolve()) : resolve()));
200	    await this.idle();
201	    await this.sendOutbox();
202	    await this.idle();
203	    this.unflushed.push(...this.rollups.drain());
204	    await this.flush().catch(() => this.counts.errors++);
205	    await this.o.store.leave(this.o.self.id).catch(() => this.counts.errors++);
206	    this.lag.disable();
207	    await closed;
208	  }
209	
210	  /** The port the peer server is bound to (the one asked for, or the one picked for port 0). */
211	  get port(): number {
212	    const a = this.server?.address();
213	    return a && typeof a === "object" ? a.port : this.o.port;
214	  }
215	
216	  /** Resolves when every check, confirmation and write in flight has finished. */
217	  async idle(): Promise<void> {
218	    while (this.running.size > 0) await Promise.allSettled([...this.running]);
219	  }
220	
221	  health() {
222	    return {
223	      id: this.o.self.id,
224	      release: this.o.release ?? null,
225	      ready: !this.stopping && this.lastFlushAt !== null && this.now() - this.lastFlushAt < 90 &&
226	        (!this.o.canary || this.o.canary.health().status === "healthy"),
227	      canary: this.o.canary?.health() ?? null,
228	      lastFlushAt: this.lastFlushAt,
229	      location: this.o.self.location,
230	      uptimeSec: this.now() - this.startedAt,
231	      monitors: this.monitors.size,
232	      heartbeats: this.heartbeats.size,
233	      scheduled: this.wheel.size,
234	      inFlight: this.inFlight,
235	      livePeers: this.peers.length,
236	      liveProbeIds: this.peers.map((p) => p.id),
237	      homeMonitors: [...this.monitors.values()].filter((m) => !m.paused && this.order(m)[0]?.id === this.o.self.id).length,
238	      /** Monitors left unchecked because a secret header wouldn't open: a wrong `CREDENTIALS_KEY`. */
239	      unreadable: [...this.monitors.values()].filter((m) => m.headers === null).length,
240	      lagP99Ms: Math.round(this.lag.percentile(99) / 1e6),
241	    };
242	  }
243	
244	  // ── who checks what ────────────────────────────────────────────────────────
245	
246	  order(m: Monitor): ProbeInfo[] {
247	    return ranked(m.id, eligible(this.peers, m.builder));
248	  }
249	
250	  private place(m: Monitor): void {
251	    if (m.paused || m.headers === null) return this.wheel.cancel(m.id);
252	    const order = this.order(m);
253	    const k = order.findIndex((p) => p.id === this.o.self.id);
254	    if (k < 0) return this.wheel.cancel(m.id);
255	    // The first slot after the last second the wheel handled, so placing a monitor again in the
256	    // second it is due, before the tick reaches it, keeps that slot instead of skipping it.
257	    const due = nextDue(this.wheel.last, m.id, m.intervalSec, k, order.length);
258	    // A version with no outcome yet is checked once by its home within ten seconds, spread by its
259	    // id. Once per version in this process: a first check can leave nothing in the row (a failure
260	    // waiting for its second, one the other location didn't confirm), and that must not become a
261	    // check every refresh. Its turns follow from there. Not while the canary reads this box as
262	    // isolated: a failure found then can't count, so hurrying would only repeat the request every
263	    // refresh. The refresh after the network is back places it.
264	    const first = m.unchecked && k === 0 && !this.firstChecked.has(`${m.id}@${m.version}`)
265	      && this.o.canary?.health().status !== "isolated";
266	    this.wheel.schedule(m.id, Math.max(this.refusalDue(m), first ? Math.min(due, this.wheel.last + 1 + (hash32(m.id) % 10)) : due));
267	  }
268	
269	  private refusalDue(m: Monitor): number {
270	    if (!supabaseBackoff(m)) return -Infinity;
271	    const local = this.serviceChecked.get(m.id);
272	    // After a restart use the newest counted outcome across all locations: passes have no
273	    // failure row, and a later peer failure can replace the pass's location in that outcome.
274	    // A running process has its own exact start time and needn't delay for another location.
275	    const last = local?.version === m.version ? local.at
276	      : typeof m.config.__outcomeAt === "number" ? m.config.__outcomeAt : -Infinity;
277	    return last + SUPABASE_REFUSAL_SEC;
278	  }
279	
280	  /** The live set changed, or a monitor did: every placement and every home is recomputed. */
281	  private replan(): void {
282	    for (const m of this.monitors.values()) this.place(m);
283	    for (const h of this.heartbeats.values()) this.placeHeartbeat(h);
284	  }
285	
286	  private isHome(id: string): boolean {
287	    return ranked(id, eligible(this.peers, false))[0]?.id === this.o.self.id;
288	  }
289	
290	  /** Only the home judges a heartbeat. What the last refresh read decides whether something is
291	      waiting now or when the next deadline falls; the judgement itself reads the locked row. */
292	  private placeHeartbeat(h: HeartbeatMonitor): void {
293	    if (h.paused || !this.isHome(h.id)) return this.wheel.cancel(h.id);
294	    const { event, due } = plan(h.row, this.now() * 1000);
295	    if (event) void this.judge(h.id);
296	    else if (due !== null) this.wheel.schedule(h.id, Math.ceil((due + DEADLINE_MARGIN_MS) / 1000));
297	    else this.wheel.cancel(h.id);
298	  }
299	
300	  /** Judge one heartbeat until nothing is due, one event per transaction, counting each run into
301	      this location's windows; then wait on the wheel for its next deadline. Chained per monitor,
302	      like outcomes, so a refresh and a deadline never judge it twice at once. */
303	  judge(id: string): Promise<void> {
304	    const store = this.o.store;
305	    if (!store.judgeHeartbeat) return Promise.resolve();
306	    const prev = this.chains.get(id) ?? Promise.resolve();
307	    const next = prev.then(async () => {
308	      try {
309	        for (let i = 0; i < JUDGE_BATCH; i++) {
310	          const r = await store.judgeHeartbeat!(id, this.o.self.location);
311	          for (const run of r.runs) this.rollups.record(id, Math.floor(run.at / 1000), { ok: run.ok, ms: null });
312	          if (r.applied === "written") {
313	            this.counts.judged++;
314	            continue;
315	          }
316	          const h = this.heartbeats.get(id);
317	          if (r.applied === "unchanged" && r.due !== null && h && !h.paused && this.isHome(id)) {
318	            this.wheel.schedule(id, Math.ceil((r.due + DEADLINE_MARGIN_MS) / 1000));
319	          }
320	          return;
321	        }
322	        this.wheel.schedule(id, this.wheel.last + 1);
323	      } catch {
324	        // Rolled back; the next refresh or deadline judges it again from the durable row.
325	        this.counts.errors++;
326	      }
327	    });
328	    this.chains.set(id, next);
329	    void next.finally(() => {
330	      if (this.chains.get(id) === next) this.chains.delete(id);
331	    });
332	    return this.track(next);
333	  }
334	
335	  /** Tracked, so a stop waits for a heartbeat already on its way: one landing after `leave` would
336	      put this probe back in the live set for two minutes. */
337	  beat(): Promise<void> {
338	    return this.track(this.heartbeatAndReplan());
339	  }
340	
341	  private async heartbeatAndReplan(): Promise<void> {
342	    await this.o.store.heartbeat(this.o.self);
343	    const live = await this.o.store.liveProbes();
344	    const key = (ps: ProbeRow[]) => ps.map((p) => `${p.id}@${p.url}`).join(",");
345	    if (key(live) === key(this.peers)) return;
346	    this.peers = live;
347	    // Reload configuration when ownership changes; counting is already in the shared row.
348	    await this.refresh();
349	  }
350	
351	  /** Refresh configuration and scheduling evidence, never reducer counters. The generation
352	      prevents a slow read from replacing a later edit or pause. */
353	  private refreshes = 0;
354	  /** `id@version` of each monitor version this probe has given its quick first check. */
355	  private firstChecked = new Set<string>();
356	  async refresh(): Promise<void> {
357	    const call = ++this.refreshes;
358	    // A heartbeat read that fails (a database without migration 019) never stops the checks:
359	    // the heartbeats keep what the last read had, and the error is counted.
360	    const heartbeatsRead = this.o.store.loadHeartbeats
361	      ? this.o.store.loadHeartbeats().catch(() => {
362	          this.counts.errors++;
363	          return null;
364	        })
365	      : Promise.resolve([]);
366	    const [rows, beats] = await Promise.all([this.o.store.loadMonitors(), heartbeatsRead]);
367	    if (call !== this.refreshes) return;
368	    if (beats) {
369	      const beating = new Set(beats.map((h) => h.id));
370	      for (const h of beats) this.heartbeats.set(h.id, h);
371	      for (const id of this.heartbeats.keys()) {
372	        if (beating.has(id)) continue;
373	        this.heartbeats.delete(id);
374	        this.wheel.cancel(id);
375	      }
376	    }
377	    const seen = new Set(rows.map((m) => m.id));
378	    for (const m of rows) {
379	      // A new version (an edit, a pause, a resume) starts its windows over. What this probe holds
380	      // for windows that end after the edit is the old version's: an old address's checks, or
381	      // ones judged by the old settings, which would otherwise reach the rollups as the new
382	      // version's, its first numbers among them. The database drops the rows of those windows
383	      // at the edit (020).
384	      const was = this.monitors.get(m.id);
385	      if (was && was.version !== m.version) this.forgetWindows(m.id, versionSec(m.version));
386	      this.monitors.set(m.id, m);
387	    }
388	    for (const id of this.monitors.keys()) {
389	      if (seen.has(id)) continue;
390	      this.monitors.delete(id);
391	      this.serviceChecked.delete(id);
392	      this.wheel.cancel(id);
393	    }
394	    this.replan();
395	    // Not tracked: a stop doesn't wait on a registry. It is asked between lookups, and a write
396	    // cut off by the store closing is counted and done again by the next leader.
397	    if (this.o.timers !== false) void this.domains();
398	  }
399	
400	  // ── domains ────────────────────────────────────────────────────────────────
401	
402	  /** When the leader last looked at each host, in seconds by this probe's clock. */
403	  private domainLooked = new Map<string, number>();
404	  private domainsRunning = false;
405	
406	  /** The leader's pass over the SSL monitors' hosts it hasn't looked at within the hour. Every
407	      refresh asks, so a new host is looked up within one (`domains.ts`). Not the leader, a store
408	      that keeps no domains, or a pass already running: nothing. */
409	  async domains(): Promise<void> {
410	    const store = this.o.store;
411	    if (!this.rdap || !store.loadDomains || !store.recordDomain || this.domainsRunning || this.stopping) return;
412	    if (domainLeader(this.peers)?.id !== this.o.self.id) return;
413	    const now = this.now();
414	    const hosts = new Set<string>();
415	    for (const m of this.monitors.values()) {
416	      if (m.type !== "ssl" || m.paused) continue;
417	      const host = String(m.config.host ?? m.target).toLowerCase();
418	      if ((this.domainLooked.get(host) ?? -Infinity) <= now - DOMAIN_LOOK_SEC) hosts.add(host);
419	    }
420	    if (hosts.size === 0) return;
421	    this.domainsRunning = true;
422	    try {
423	      const r = await domainPass({ loadDomains: (h) => store.loadDomains!(h), recordDomain: (h, x) => store.recordDomain!(h, x) },
424	        this.rdap, [...hosts], now * 1000, () => this.stopping);
425	      // What the pass left (its cap, a registry that asked for less) is looked at next refresh.
426	      for (const h of hosts) if (!r.deferred.has(asciiHost(h) ?? h)) this.domainLooked.set(h, now);
427	      this.counts.domains += r.looked;
428	      this.counts.errors += r.errors;
429	    } catch {
430	      // The read failed: nothing was looked up, and the next refresh tries again.
431	      this.counts.errors++;
432	    } finally {
433	      this.domainsRunning = false;
434	    }
435	  }
436	
437	  // ── checks ─────────────────────────────────────────────────────────────────
438	
439	  /** Second looks wait in a queue of their own, ahead of ordinary checks and first come first
440	      served: they are about 1% of checks, a queue full of timeouts is exactly when a failure needs
441	      confirming, and the one that has waited longest is closest to its 30 s. */
442	  private acquire(urgent: boolean): Promise<void> {
443	    if (this.inFlight < (this.o.maxInFlight ?? 256)) {
444	      this.inFlight++;
445	      return Promise.resolve();
446	    }
447	    return new Promise((resolve) => (urgent ? this.waitingUrgent : this.waiting).push(resolve));
448	  }
449	
450	  private release(): void {
451	    const next = this.waitingUrgent.shift() ?? this.waiting.shift();
452	    if (next) next();
453	    else this.inFlight--;
454	  }
455	
456	  async runCheck(m: Monitor, urgent = false): Promise<Located | null> {
457	    await this.acquire(urgent);
458	    try {
459	      const current = this.monitors.get(m.id);
460	      const scheduled = current?.version === m.version ? current : m;
461	      // Check after acquiring a slot: a queued ordinary check and a peer's second look must
462	      // share the same per-location allowance. A skipped check is no result, never evidence.
463	      if (this.now() < this.refusalDue(scheduled)) return null;
464	      if (m.type === "supabase") this.serviceChecked.set(m.id, { version: m.version, at: this.now() });
465	      const c = m.config;
466	      const opts = { allow: this.o.checks?.allow, ca: this.o.checks?.ca };
467	      let r: CheckResult;
468	      if (m.type === "http") {
469	        r = await checkHttp(
470	          {
471	            url: m.target,
472	            method: (c.method as "GET" | "HEAD" | "POST") ?? "GET",
473	            body: typeof c.body === "string" ? c.body : undefined,
474	            expect: String(c.expect ?? "2xx"),
475	            keyword: (c.keyword as string | null) ?? null,
476	            slowMs: Number(c.slowMs ?? monitorDefaults.slowMs.http),
477	            timeoutSec: Number(c.timeoutSec ?? 15),
478	            assertions: (c.assertions as Assertion[]) ?? [],
479	            headers: m.headers ?? undefined,
480	          },
481	          opts,
482	        );
483	      } else if (m.type === "stripe") {
484	        r = await checkStripe(c as StripeConfig, m.headers?.[SERVICE_KEY] ?? "", { fetch: this.o.checks?.serviceFetch ?? serviceFetch(opts), now: () => this.now() * 1000,
485	          runtime: c.__runtime as StripeRuntime, recovering: c.__state === "down" });
486	      } else if (m.type === "supabase") {
487	        r = await checkSupabase(c as SupabaseConfig, m.headers?.[SERVICE_KEY] ?? "", { fetch: this.o.checks?.serviceFetch ?? serviceFetch(opts) });
488	      } else if (m.type === "tcp") {
489	        r = await checkTcp({ host: String(c.host), port: Number(c.port), tls: c.tls === true, slowMs: Number(c.slowMs ?? monitorDefaults.slowMs.tcp) }, opts);
490	      } else if (m.type === "ssl") {
491	        r = await checkCert({ host: String(c.host ?? m.target), port: c.port === undefined ? undefined : Number(c.port) }, opts);
492	      } else {
493	        r = await checkDns({ record: c.record as DnsRecord, name: String(c.name), expected: String(c.expected) }, this.o.checks?.dnsAsk);
494	      }
495	      this.counts.checks++;
496	      // Refuse before every path that can record a failure: rollups, early first writes,
497	      // reports, self-rechecks and incoming confirmations all pass here. Successful checks
498	      // remain useful evidence during isolation and need no network-health veto.
499	      if (!r.ok && this.o.canary && !(await this.o.canary.admitFailure())) return null;
500	      // A check of a version replaced while it ran counts for neither: its window now belongs to
501	      // the new version (`forgetWindows`).
502	      if (this.monitors.get(m.id)?.version === m.version) this.rollups.record(m.id, this.now(), r);
503	      return { ...r, location: this.o.self.location };
504	    } finally {
505	      this.release();
506	      const current = this.monitors.get(m.id);
507	      if (m.type === "supabase" && current) this.place(current);
508	    }
509	  }
510	
511	  /** Everything due by now, started; their next slots placed first, so a slow check never
512	      delays its own next one. */
513	  tick(): Promise<void>[] {
514	    const started: Promise<void>[] = [];
515	    const spread = this.o.spreadMs ?? 1000;
516	    for (const id of this.wheel.advance(this.now())) {
517	      if (this.heartbeats.has(id)) {
518	        started.push(this.judge(id));
519	        continue;
520	      }
521	      const m = this.monitors.get(id);
522	      if (!m || m.paused || m.headers === null) continue;
523	      // This version's first check from here, whichever turn it came on.
524	      const first = m.unchecked === true && !this.firstChecked.has(`${m.id}@${m.version}`);
525	      if (m.unchecked) this.firstChecked.add(`${m.id}@${m.version}`);
526	      this.place(m);
527	      const delay = spread > 0 ? hash32(`${m.id}/offset`) % spread : 0;
528	      const run = delay > 0 ? new Promise((r) => setTimeout(r, delay)).then(() => this.checkAndReport(m, first)) : this.checkAndReport(m, first);
529	      started.push(this.track(run));
530	    }
531	    return started;
532	  }
533	
534	  private track<T>(p: Promise<T>): Promise<T> {
535	    this.running.add(p);
536	    p.finally(() => this.running.delete(p)).catch(() => {});
537	    return p;
538	  }
539	
540	  private async checkAndReport(m: Monitor, firstHere = false): Promise<void> {
541	    const atSec = this.now();
542	    try {
543	      const first = await this.runCheck(m);
544	      if (!first) {
545	        // An isolated network, or a Supabase refusal's backoff, supplied no first observation. The next refresh can schedule the
546	        // quick first check again; do not make a new six-hour monitor wait six hours for it.
547	        if (firstHere) this.firstChecked.delete(`${m.id}@${m.version}`);
548	        return;
549	      }
550	      // Before the second look a failure waits for: the window says what was seen here, now.
551	      if (firstHere) void this.track(this.writeFirst(m.id));
552	      const confirm = needsConfirmation(m.type, first) ? await this.confirm(m) : undefined;
553	      // A confirmed failure needs both checks; a failure nobody else could look at stays
554	      // unconfirmed, and the state machine counts it as nothing.
555	      // Supabase's persisted observation time bounds both requests, including time in the
556	      // queue and the second look, so a restart cannot retry earlier than either location did.
557	      this.deliver({ monitorId: m.id, version: m.version, outcome: { first, ...(confirm ? { confirm } : {}) },
558	        atSec: m.type === "supabase" ? this.now() : atSec });
559	    } catch {
560	      this.counts.errors++;
561	    }
562	  }
563	
564	  /** The second look at a failure: from each other live location in turn until one answers.
565	      From here, after a pause, only when no other location can look: none is live, or every one
566	      answered that it can't open this monitor's headers. A peer that doesn't answer (restarting,
567	      refusing the signature, or not yet holding the monitor as this probe does) is not the same as
568	      no peer, and a failure only this box can see must not be confirmed by this box. */
569	  private async confirm(m: Monitor): Promise<Located | undefined> {
570	    this.counts.confirms++;
571	    const others = confirmersFor(this.order(m), this.o.self.id, m.builder);
572	    const fromHere = async () => {
573	      await new Promise((resolve) => setTimeout(resolve, (this.o.recheckAfterSec ?? 20) * 1000));
574	      return (await this.runCheck(m, true)) ?? undefined;
575	    };
576	    if (others.length === 0) return fromHere();
577	    const deadline = Date.now() + CONFIRM_WITHIN_MS;
578	    let declined = 0;
579	    for (const peer of others) {
580	      const row = this.peers.find((p) => p.id === peer.id);
581	      const left = deadline - Date.now();
582	      if (left <= 0) break;
583	      const r = row && (await askConfirm(this.o.secret, row, m.id, m.version, left));
584	      if (r === "declined") declined++;
585	      else if (r) return r;
586	    }
587	    if (declined === others.length) return fromHere();
588	    this.counts.unconfirmed++;
589	    return undefined;
590	  }
591	
592	  /** A peer's request for a second look. No answer for a monitor not loaded yet, paused, or held
593	      here as another version than the asker checked: a second look at another address or config
594	      would confirm nothing about the first. `cannot` for one whose secret headers won't open
595	      here: without them the check would fail, and confirm a failure that isn't there. */
596	  private async confirmHere(monitorId: string, version: string): Promise<Located | "cannot" | null> {
597	    const m = this.monitors.get(monitorId);
598	    if (!m || m.paused || m.version !== version) return null;
599	    if (m.headers === null) return "cannot";
600	    return this.track(this.runCheck(m, true));
601	  }
602	
603	  // ── outcomes and the state machine ─────────────────────────────────────────
604	
605	  private deliver(r: Report): void {
606	    const m = this.monitors.get(r.monitorId);
607	    if (!m) return;
608	    if (this.order(m)[0]?.id === this.o.self.id) void this.track(this.applyOutcome(r));
609	    else if (this.outbox.length < MAX_OUTBOX) this.outbox.push(r);
610	  }
611	
612	  /** Reports for other homes, sent once a second. The home is looked up again at sending, so a
613	      report for a probe that has since dropped out goes to the monitor's new home. */
614	  async sendOutbox(): Promise<void> {
615	    if (this.outbox.length === 0) return;
616	    // In check order: a report that failed to send goes back behind newer ones, and a home steps
617	    // the state machine in the order reports arrive.
618	    const batch = this.outbox.sort((a, b) => a.atSec - b.atSec);
619	    this.outbox = [];
620	    const byHome = new Map<string, Report[]>();
621	    for (const r of batch) {
622	      const m = this.monitors.get(r.monitorId);
623	      const home = m && this.order(m)[0];
624	      if (!home) continue;
625	      if (home.id === this.o.self.id) {
626	        void this.track(this.applyOutcome(r));
627	        continue;
628	      }
629	      byHome.set(home.id, [...(byHome.get(home.id) ?? []), r]);
630	    }
631	    await Promise.all(
632	      [...byHome].map(async ([id, reports]) => {
633	        const row = this.peers.find((p) => p.id === id);
634	        if (row && (await sendReports(this.o.secret, row, reports))) this.counts.reported += reports.length;
635	        else this.outbox.push(...reports.slice(0, MAX_OUTBOX - this.outbox.length));
636	      }),
637	    );
638	  }
639	
640	  private receive(reports: Report[]): void {
641	    for (const r of reports) {
642	      if (typeof r?.monitorId === "string" && typeof r.version === "string" && Number.isInteger(r.atSec) && typeof r.outcome?.first?.location === "string") this.deliver(r);
643	    }
644	  }
645	
646	  /** Preserve this home's arrival order while writes await a connection. Other homes serialize
647	      on the row lock. A refresh cannot affect an outcome already sent to the store. */
648	  private chains = new Map<string, Promise<void>>();
649	
650	  private applyOutcome(r: Report): Promise<void> {
651	    const prev = this.chains.get(r.monitorId) ?? Promise.resolve();
652	    const next = prev.then(async () => {
653	      try {
654	        // Even a report newer than our cached configuration goes to the row: its version, pause,
655	        // state and counters decide. A stale cache cannot reject a valid recovery or invent one.
656	        const done = await this.o.store.apply(r);
657	        if (done === "moved") this.counts.moved++;
658	        else if (done === "duplicate") this.counts.duplicates++;
659	        else if (done === "written" || done === "unchanged") this.counts.applied++;
660	      } catch {
661	        // The transaction rolled back; the next outcome still starts from the durable row.
662	        this.counts.errors++;
663	      }
664	    });
665	    this.chains.set(r.monitorId, next);
666	    void next.finally(() => {
667	      if (this.chains.get(r.monitorId) === next) this.chains.delete(r.monitorId);
668	    });
669	    return next;
670	  }
671	
672	  // ── rollups ────────────────────────────────────────────────────────────────
673	
674	  /** A new monitor's window so far, written now rather than when the window closes. A write that
675	      fails waits with the closed windows for the next flush, which merges it the same way. */
676	  private async writeFirst(monitorId: string): Promise<void> {
677	    const rows = this.rollups.take(monitorId);
678	    if (rows.length === 0) return;
679	    try {
680	      await this.o.store.flushRollups(rows);
681	      this.lastFlushAt = this.now();
682	      this.counts.firstWrites++;
683	    } catch {
684	      this.unflushed.push(...rows);
685	      this.counts.errors++;
686	    }
687	  }
688	
689	  async flush(): Promise<void> {
690	    const rows = merged([...this.unflushed, ...this.rollups.closed(this.now(), FLUSH_GRACE_SEC)]);
691	    this.unflushed = [];
692	    try {
693	      await this.o.store.flushRollups(rows);
694	      this.lastFlushAt = this.now();
695	    } catch (err) {
696	      // Kept with whatever failed while this one was out (a first write), not in place of it.
697	      this.unflushed = rows.concat(this.unflushed);
698	      throw err;
699	    }
700	  }
701	
702	  /** The monitor's windows that end after `sinceSec`, dropped from memory and from the writes
703	      waiting to be retried. */
704	  private forgetWindows(monitorId: string, sinceSec: number): void {
705	    this.rollups.forget(monitorId, sinceSec);
706	    this.unflushed = this.unflushed.filter((r) => r.monitorId !== monitorId || r.windowStart + WINDOW_SEC <= sinceSec);
707	  }
708	}
