1	import type { CheckResult } from "../src/checks/types";
2	
3	/* One state machine for every checked type (`spec.md § 2`). Pure: the store reads its state from
4	   the locked monitor row, steps an outcome, and commits the next state and effects together.
5	   Homes keep only check configuration, never a second copy of these counters.
6	
7	   - A monitor starts `up` after its first passing check, and reaches `down` only through
8	     confirmation: a failure is re-checked at once from another location, and only a second
9	     failure counts. DNS asks the same two public resolvers from anywhere, so its confirmation is
10	     a second failing check in a row instead. A certificate that is invalid is the same from
11	     everywhere, so it is down at once; a certificate that can't be reached is confirmed.
12	   - `degraded` is three passing checks in a row over the slow threshold, and ends at the first
13	     that isn't.
14	   - A failure the second location didn't confirm is one location's noise. It counts toward
15	     neither streak and breaks neither, so a location that can't reach a target never holds an
16	     incident open or a monitor degraded.
17	   - An incident opens with the transition to `down`, and the monitor leaves `down` after two
18	     passes in a row; the store closes the incident with that transition (`store.ts`), and writes
19	     any transition only from the state the row holds, so the two move together. A version change
20	     resets the counters in SQL. Degraded still means slow until a fast pass, even after a reset.
21	
22	   `paused` is not here: a paused monitor isn't scheduled at all, and its state is kept.
23	
24	   A heartbeat goes through the same reducer, with two differences (`spec.md § 3.3, § 5`): its
25	   grace window is its confirmation, so a missed deadline, a `/fail`, a false assertion or a
26	   stuck run is down at once, and it recovers on the next good ping rather than after two
27	   passes, which for a daily job would hold an incident open a day after the job recovered
28	   (`AGENTS.md § 2.8`). What counts as each of those is `heartbeat.ts`. */
29	
30	export type State = "up" | "degraded" | "down";
31	export type CheckedType = "http" | "tcp" | "ssl" | "dns" | "stripe" | "supabase";
32	/** Every type the reducer steps: the checked ones, and heartbeats, whose outcomes the home
33	    derives from what the receiver recorded (`heartbeat.ts`). */
34	export type JudgedType = CheckedType | "heartbeat";
35	
36	export type MonitorState = {
37	  state: State | null;
38	  slowStreak: number;
39	  /** Passes in a row while down. */
40	  passStreak: number;
41	  /** Failing checks in a row that haven't moved the state yet (DNS's two-in-a-row). */
42	  failStreak: number;
43	};
44	
45	export const fresh = (state: State | null = null): MonitorState => ({ state, slowStreak: 0, passStreak: 0, failStreak: 0 });
46	
47	export type Located = CheckResult & { location: string };
48	export type Outcome = { first: Located; confirm?: Located };
49	
50	export type Evidence = {
